installer-gui-script.script:
function hardwareIsAppleSilicon() {
    return system.sysctl('hw.optional.arm64') == 1;
}

function currentSystemMajorVersion() {
    return parseInt(system.version.ProductVersion.split('.')[0], 10);
}

function siriRemoteSupportWasPreviouslyInstalled() {
    return system.files.fileExistsAtPath('/var/db/receipts/com.hd838a.RemoteMic.siri-remote.plist') ||
        system.files.fileExistsAtPath('/var/db/receipts/com.hd838a.RemoteMic.siri-remote.bom') ||
        system.files.fileExistsAtPath('/Library/PrivilegedHelperTools/com.hd838a.SayAll.AppleRemoteHCIService') ||
        system.files.fileExistsAtPath('/Library/LaunchDaemons/com.hd838a.SayAll.AppleRemoteHCIService.plist');
}

function installationCheck() {
    if (hardwareIsAppleSilicon()) {
        my.result.type = 'Fatal';
        my.result.message = system.localizedString('wrong_architecture_intel');
        return false;
    }
    if (currentSystemMajorVersion() < 13) {
        my.result.type = 'Fatal';
        my.result.message = system.localizedString('unsupported_system_intel');
        return false;
    }
    return true;
}
